var t=[{title:`Stel het touw af`,text:`Kies een touw dat soepel draait zonder je voeten te raken. Een gebruikelijke eerste afstelling is bij het midden staan en de handvatten tot je onderste borst of oksels optillen, en dan bijstellen voor de dikte van het touw en je vaardigheid. Zorg dat je voor het springen veel ruimte boven je, opzij en op de vloer hebt.`},{title:`Leer een kleine basissprong`,text:`Houd je ellebogen comfortabel dicht bij je ribben en draai het touw vooral vanuit de polsen, zonder met je hele armen te zwaaien. Gebruik korte, ontspannen sprongen die net hoog genoeg zijn om over het touw te komen, zonder je knieën hoog op te trekken. Land zacht en laat je enkels en knieën buigen; probeer je benen niet helemaal stijf te houden.`},{title:`Voeg geleidelijk variaties toe`,text:`Begin met enkele draaiingen, ook als er maar twee of drie lukken voordat je opnieuw moet beginnen. Ga door naar korte continue sets en voeg dan wisselende voeten, een boxerstap of zijwaartse verplaatsingen toe zodra je timing verbetert. Trucs zoals double-unders komen na een betrouwbaar basisritme.`},{title:`Vermijd te veel impact en frustratie`,text:`Herhaald springen belast je kuiten en achillespezen, dus grote plotselinge toenames kunnen ze pijnlijk maken. Blijft het touw haken, dan kan het te lang, te kort of slecht getimed zijn; het betekent niet dat je niet fit bent. Draag schoenen en gebruik een ondergrond met goede grip en vermijd gladde tegelvloeren en drukke ruimtes.`},{title:`TrainUp gebruiken`,text:`Het schema bevat touwtjespringen alleen als je uitrusting en je Profielinstellingen voor plafondhoogte, ondergrond, springen en geluid dat toelaten. Houd de intervallen eerst kort. Houdt je vaardigheid of de impact je tegen, dan houden schaduwboksen of marcheren de training gaande.`}];var i=[{label:`CDC: de intensiteit van activiteit meten en de praattest`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Beweegaanbevelingen van de CDC voor volwassenen`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var o={sections:t,sources:i};export{o as default,t as sections,i as sources};